<a class="back" href="/dashboard">← Dashboard</a><div class="actions" style="justify-content:space-between"><h1>Staff</h1><a class="btn" href="/staff/new">Add staff</a></div><table><tr><th>Username</th><th>Full name</th><th>Actions</th></tr><?php foreach($staff as $m): ?><tr><td><?= esc($m['username']) ?></td><td><?= esc($m['full_name']) ?></td><td class="actions"><a class="btn secondary" href="/staff/<?= $m['id'] ?>/edit">Edit</a><form method="post" action="/staff/<?= $m['id'] ?>" onsubmit="return confirm('Delete this staff member?')" style="padding:0;border:0;box-shadow:none"><?= csrf_field() ?><input type="hidden" name="_method" value="DELETE"><button class="btn danger">Delete</button></form></td></tr><?php endforeach ?></table>
